	}
}

func TestAction_String(t *testing.T) {
	t.Parallel()

	tests := []struct {
		action Action
		want   string
	}{
		{ActionCondense, "Condense"},
		{ActionCondenseIfFilesTouched, "CondenseIfFilesTouched"},
		{ActionDiscardIfNoFiles, "DiscardIfNoFiles"},
